function draw(input) {
 const {board,width,height,params}=input;
 const P=VisualBook.palette, n=Number(params.n), mass=[];
 let pk=Math.pow(0.5,n), expected=0;
 for(let k=0;k<=n;k++) {
  const j=Math.min(k,n-k); mass[j]=(mass[j]||0)+pk;
  if(k<n) pk=pk*(n-k)/(k+1);
 }
 const probabilities=mass.map((p,j)=>{expected+=p*j/n;return {error:j/n,probability:p};});
 const mobile=width<600;
 board.text('mean','平均训练 '+expected.toFixed(3),22,26,{color:P.blue,size:15});
 board.text('risk','泛化 0.500',mobile?22:width-160,mobile?50:26,{color:P.orange,size:15});
 const f=board.axes('distribution',{xDomain:[0,0.55],yDomain:[0,0.55],xLabel:'训练误差',yLabel:'出现概率',box:[54,mobile?86:68,width-25,height-76],grid:true});
 probabilities.forEach((v,j)=>{
  const bw=Math.min(32,f.unitX/n*.68);
  board.rect('mass-'+j,f.x(v.error)-bw/2,f.y(v.probability),bw,f.y(0)-f.y(v.probability),P.blue,{opacity:0.76});
 });
 board.line('half',f.x(.5),f.top,f.x(.5),f.bottom,P.orange,2,.8);
 board.circle('expected',f.x(expected),f.y(0),4,P.blue);
 board.text('caption',n+' 次独立投掷 · 每次按多数类预测',width/2,height-15,{anchor:'middle',size:13,color:P.muted});
 return {n,probabilities,probabilitySum:mass.reduce((a,b)=>a+b,0),expectedTrainingError:expected,generalizationError:.5,originalExample:{labels:[0,1,1,1,0,1],trainingError:2/6},convention:'Exact binomial probabilities aggregated by min(k,n-k)/n; no simulation.'};
}

function draw(input) {
 const {board,width,height,params}=input, P=VisualBook.palette;
 const degree=Number(params.degree), epsilon=Number(params.epsilon);
 const xs=Array.from({length:11},(_,i)=>-1+i/5);
 const truth=x=>5+1.2*x-1.7*x*x+(5.6/6)*x*x*x;
 const ys=xs.map((x,i)=>truth(x)+(i===5?epsilon:0));
 const cols=degree+1, Q=[], R=Array.from({length:cols},()=>Array(cols).fill(0));
 for(let j=0;j<cols;j++){
  let v=xs.map(x=>Math.pow(x,j));
  for(let pass=0;pass<2;pass++) for(let k=0;k<j;k++){
   const r=v.reduce((s,a,i)=>s+a*Q[k][i],0);R[k][j]+=r;v=v.map((a,i)=>a-r*Q[k][i]);
  }
  R[j][j]=Math.hypot(...v);Q[j]=v.map(a=>a/R[j][j]);
 }
 const c=Q.map(q=>q.reduce((s,a,i)=>s+a*ys[i],0)), w=Array(cols).fill(0);
 for(let j=cols-1;j>=0;j--){let a=c[j];for(let k=j+1;k<cols;k++)a-=R[j][k]*w[k];w[j]=a/R[j][j];}
 const predict=x=>w.reduceRight((s,a)=>s*x+a,0);
 const points=Array.from({length:401},(_,i)=>{const x=-1+i/200;return[x,predict(x)];});
 const mean=points.map(([x])=>[x,truth(x)]);
 const mse=xs.reduce((s,x,i)=>s+Math.pow(predict(x)-ys[i],2),0)/11;
 const gridMSE=points.reduce((s,[x,y])=>s+Math.pow(y-truth(x),2),0)/points.length;
 const mobile=width<600;
 const num=v=>VisualBook.formatNumber(v,{precision:3});
 board.text('train','训练 MSE '+num(mse),22,25,{color:P.blue,size:14});
 board.text('probe','网格偏差² '+num(gridMSE),mobile?22:width-240,mobile?48:25,{color:P.ink,size:14});
 const f=board.axes('fit',{xDomain:[-1.08,1.08],yDomain:[0,7],xLabel:'x',yLabel:'y',box:[48,mobile?80:62,width-22,height-87],grid:true});
 board.curve('truth',f,mean,{color:P.muted,width:2,opacity:.65});
 board.curve('polynomial',f,points,{color:P.blue,width:2.5});
 xs.forEach((x,i)=>board.circle('sample-'+i,f.x(x),f.y(ys[i]),i===5?5:3.4,i===5?P.orange:P.ink));
 board.line('perturbation',f.x(0),f.y(truth(0)),f.x(0),f.y(ys[5]),P.orange,2,1);
 board.line('legend-fit',22,height-49,42,height-49,P.blue,2.5);
 board.text('legend-fit-label',degree+' 阶最小二乘',49,height-45,{size:13,color:P.blue});
 board.line('legend-truth',mobile?22:width-188,mobile?height-25:height-49,mobile?42:width-168,mobile?height-25:height-49,P.muted,2,.65);
 board.text('legend-truth-label','三阶生成均值',mobile?49:width-161,mobile?height-21:height-45,{size:13,color:P.muted});
 return {degree,epsilon,xs,ys,coefficients:w,trainingMSE:mse,gridMSE,curveRange:[Math.min(...points.map(p=>p[1])),Math.max(...points.map(p=>p[1]))],gridCount:401,gridDomain:[-1,1],convention:'11 fixed inputs, only x=0 label perturbed. QR least squares, not SGD; grid squared bias to known mean is not test/generalization error.'};
}
